function keyspace(alphabet, length) {
  return alphabet ** length;
}

function secondsToTry(guesses, perSecond) {
  return guesses / perSecond;
}

function slowdownFactor(fastRate, slowRate) {
  return fastRate / slowRate;
}

function averageCrackSeconds(alphabet, length, perSecond) {
  const combinations = alphabet ** length;
  return combinations / 2 / perSecond;
}

function minLengthToExceed(alphabet, perSecond, targetSeconds) {
  let length = 1;
  while (alphabet ** length / 2 / perSecond < targetSeconds) {
    length += 1;
  }
  return length;
}

